// Server-only, original assessment items. Difficulty is an authored blueprint;
// it has not been calibrated on participants and does not certify a profession.
// Family tags are the union of the competencies its four distinct tasks assess.
const family = (id, topic, difficulty, rows) => ({
  id, topic, difficulty,
  skills: [...new Set(rows.flatMap(([skills]) => skills))],
  variants: rows.map(([skills, text, options, correct], index) => ({
    id: `${id}-${String.fromCharCode(97 + index)}`, skills, text, options, correct,
  })),
});

